import React from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import { useAppNavigate } from '../../hooks/useAppNavigate';
import { showDevNav, isStandalone } from '../../dev/isStandalone';
import { MFE_PACKAGE_NAME } from '../../config/mfeIdentity';
import { isKnownScykAppRoute, isScykShellPath, SCYK_HOME } from '../../config/scykRoutes';

/** MFE-local 404 — không dùng common-components NotFoundPage (cần root auth slice). */
export const SimpleNotFoundPage: React.FC = () => {
  const navigate    = useNavigate();
  const appNavigate = useAppNavigate();
  const location = useLocation();
  const home = showDevNav ? '/dev' : SCYK_HOME;
  const path = location.pathname;
  const isScykPath = isScykShellPath(path);
  const isRegisteredScykRoute = isKnownScykAppRoute(path);

  return (
    <div style={{ padding: '2rem', maxWidth: 520, margin: '0 auto', textAlign: 'center' }}>
      <h1 style={{ fontSize: '1.5rem', margin: '0 0 0.75rem' }}>Không tìm thấy trang</h1>
      {isScykPath && !isRegisteredScykRoute ? (
        <p style={{ margin: '0 0 0.5rem', color: '#555' }}>
          Đường dẫn không thuộc SCYK ({MFE_PACKAGE_NAME}).
        </p>
      ) : null}
      <p style={{ margin: 0 }}>
        Trang <code>{path}</code> không tồn tại
        {isRegisteredScykRoute ? ' (route chưa được mount — thử tải lại hoặc redeploy MFE)' : ' hoặc đã bị di chuyển'}.
      </p>
      <div style={{ display: 'flex', gap: 12, justifyContent: 'center', marginTop: 24, flexWrap: 'wrap' }}>
        <button type="button" onClick={() => appNavigate(SCYK_HOME, { replace: true })}>
          Về danh sách sự cố
        </button>
        <button type="button" onClick={() => navigate(-1)}>
          Quay lại
        </button>
        {showDevNav && (
          <button type="button" onClick={() => appNavigate('/dev')}>
            Dev Navigation
          </button>
        )}
        {isStandalone && (
          <span style={{ width: '100%', fontSize: '0.875rem', color: '#666' }}>
            Trang Home/Admin mở qua shell Root — không qua standalone <code>:8504</code>.
          </span>
        )}
      </div>
    </div>
  );
};
