/**
 * Tab 6 — "Phân tích với AI" visibility / behaviour.
 *
 * VITE_AI_MODE:
 *   enabled      — nút AI hoạt động (check credit + generate)
 *   coming-soon  — hiện nút disabled + badge "Sắp có"
 *   hidden       — ẩn hoàn toàn
 */
export type MedicalReportAiMode = 'enabled' | 'coming-soon' | 'hidden';

const VALID_MODES: MedicalReportAiMode[] = ['enabled', 'coming-soon', 'hidden'];

export function parseMedicalReportAiMode(raw: string | undefined): MedicalReportAiMode {
  const normalized = (raw ?? 'coming-soon').trim().toLowerCase();

  if (normalized === 'enabled' || normalized === 'true' || normalized === '1') {
    return 'enabled';
  }
  if (normalized === 'hidden' || normalized === 'hide' || normalized === 'false' || normalized === '0') {
    return 'hidden';
  }
  if (normalized === 'coming-soon' || normalized === 'coming_soon' || normalized === 'soon') {
    return 'coming-soon';
  }

  if (import.meta.env.DEV) {
    console.warn(
      `[config] Invalid VITE_AI_MODE="${raw}" — use enabled | coming-soon | hidden`,
    );
  }

  return VALID_MODES.includes(normalized as MedicalReportAiMode)
    ? (normalized as MedicalReportAiMode)
    : 'coming-soon';
}

export function isMedicalReportAiEnabled(mode: MedicalReportAiMode): boolean {
  return mode === 'enabled';
}

export function shouldShowMedicalReportAiButton(mode: MedicalReportAiMode): boolean {
  return mode !== 'hidden';
}
